contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function driving C
    // params: target address to call, arbitrary calldata, and an amount of wei to send with the call
    function run(address target, bytes memory data, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract can send the requested amount to c when calling Command
        require(address(this).balance >= amount);

        // Observe before-values
        address owner_before = c.Owner(); if (__ESBMC_reverted()) return;
        uint c_balance_before = address(c).balance;
        uint our_balance_before = address(this).balance;

        // Make the call as a try/catch to observe whether it reverts
        bool reverted;
        c.Command{value: amount}(target, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-values
        address owner_after = c.Owner(); if (__ESBMC_reverted()) return;
        uint c_balance_after = address(c).balance;
        uint our_balance_after = address(this).balance;

        // General rule:
        // - Owner never changes as a result of Command
        // - If Command reverted, c.balance and this.balance are unchanged
        // - If Command did not revert, c.balance decreased by at most `amount` (i.e., c_balance_before - c_balance_after <= amount)
        //   and this contract's balance decreased by exactly `amount` (we forwarded amount) or increased if the called target sent us funds back.
        // Expressed without subtraction that may underflow in assert: we check c_balance_after + amount >= c_balance_before
        assert(
            owner_before == owner_after
            && (
                reverted
                ? (c_balance_after == c_balance_before && our_balance_after == our_balance_before)
                : (c_balance_after + amount >= c_balance_before)
            )
        );
    }

    // allow receiving Ether from calls made by C.Command
    receive() external payable {}
}

