// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address target, bytes memory data, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address owner_before;
        try c.Owner() returns (address __r) { owner_before = __r; } catch { return; }
        uint c_balance_before = address(c).balance;
        uint our_balance_before = address(this).balance;
        bool reverted;
        try c.Command{value: amount}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address owner_after;
        try c.Owner() returns (address __r) { owner_after = __r; } catch { return; }
        uint c_balance_after = address(c).balance;
        uint our_balance_after = address(this).balance;
        assertTrue(owner_before == owner_after
            && (
                reverted
                ? (c_balance_after == c_balance_before && our_balance_after == our_balance_before)
                : (c_balance_after + amount >= c_balance_before)
            ));
    }

    function testFuzz_run(address target, bytes memory data, uint256 amount) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, data, amount);
    }

    receive() external payable {}
}
